#!/usr/bin/env node

import { constants } from "node:fs";
import { access, mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const postinstall = process.argv.includes("--postinstall");
const packageRoot = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const projectRoot = path.resolve(postinstall ? process.env.INIT_CWD || process.cwd() : process.cwd());
const workflowPath = path.join(projectRoot, ".github", "workflows", "iykyk.yml");
const templatePath = path.join(packageRoot, "templates", "iykyk.yml");

async function exists(filePath) {
  try {
    await access(filePath, constants.F_OK);
    return true;
  } catch {
    return false;
  }
}

async function install() {
  if (!(await exists(path.join(projectRoot, "package.json")))) {
    const message = `IYKYK: ${projectRoot} is not an npm project; no workflow was installed.`;
    if (postinstall) {
      console.log(message);
      return;
    }
    throw new Error(message);
  }

  const template = await readFile(templatePath, "utf8");

  if (await exists(workflowPath)) {
    const current = await readFile(workflowPath, "utf8");
    if (current === template) {
      console.log("IYKYK: workflow is already installed.");
      return;
    }

    console.log(
      `IYKYK: left existing workflow unchanged at ${path.relative(projectRoot, workflowPath)}.\n` +
        "Run `npx iykyk-install` after moving or removing that file if you want the standard workflow.",
    );
    return;
  }

  await mkdir(path.dirname(workflowPath), { recursive: true });
  await writeFile(workflowPath, template, { flag: "wx" });
  console.log(`IYKYK: installed ${path.relative(projectRoot, workflowPath)}.`);
  console.log("Commit that file; IYKYK will run automatically whenever a pull request changes.");
}

install().catch((error) => {
  console.error(error.message);
  process.exitCode = 1;
});
